function initializeMockPresenca() {
    // Só inicializar presença se o servidor ainda não tem dados
    for (const key in MOCK_PRESENCA_INICIAL) {
        if (!DataStore.get(key)) {
            DataStore.set(key, MOCK_PRESENCA_INICIAL[key]);
        }
    }
    // Garantir produtos iniciais (storage.js já inicializa, mas por segurança)
    if (!DataStore.get("produtos_todos")) {
        DataStore.set("produtos_todos", MOCK_PRODUTOS_INICIAIS);
    }
}

if (typeof DataStore !== "undefined") {
    setTimeout(initializeMockPresenca, 150);
} else {
    document.addEventListener("DOMContentLoaded", () => setTimeout(initializeMockPresenca, 300));
}
